    .bin_bitwise_xor => {
    if (p.should_fold_typescript_constant_expressions) {
                    if (Expr.extractNumericValues(e_.left.data, e_.right.data)) |vals| {
                        _ = &vals;
                        return p.newExpr(E.Number{ .value = @floatFromInt((floatToInt32(vals[0]) ^ floatToInt32(vals[1]))) }, v.loc);
                    }
                }
