                    if (Expr.extractStringValues(e_.left.data, e_.right.data, p.allocator)) |vals| {
                        _ = &vals;
                        return p.newExpr(E.Boolean{ .value = (vals[0].order(vals[1]) == .gt) }, v.loc);
