                            }
                        }
                    }
                }
    },
    else => {
    
    },
    }
                return Expr{ .loc = v.loc, .data = .{ .e_binary = e_ } };
        }
    
    pub fn checkAndPrepare(v: *BinaryExpressionVisitor, p: *P) ?Expr {
                return checkAndPrepareImpl(P, v, p);
        }
    };
};
